function EXTRA(R,ICON){
 /* hook: one clap goes in, the hall rings back; any music goes in, the hall's sound comes out */
 ICON.sgClap=(x,y)=>`<g transform="translate(${x-200} ${y-85})">${SG_box(0,0,400,170,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}${SG_T(20,36,'one clap → the hall rings',{fs:24,fw:800,fill:BLU})}${SG_L(20,112,380,112,'#ADB5BD',2)}${SG_imp(44,112,60,BLU,5)}${SG_arrow(64,84,104,84,'#5C6577',3)}${SG_curve(SG_ring,0,3.2,120,380,112,40,GRN,4,200)}</g>`;
 ICON.sgSong=(x,y)=>`<g transform="translate(${x-200} ${y-85})">${SG_box(0,0,400,170,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${SG_T(20,36,'any music → that hall’s sound',{fs:24,fw:800,fill:ORG})}${SG_L(20,108,380,108,'#ADB5BD',2)}${SG_curve(SG_song,0,3,24,376,108,42,ORG,4,200)}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.sgTwoPaths=(x,y)=>{const bx=(X,Y,t)=>SG_box(X,Y,110,56,{fill:'#E3FAF1',st:ACC,sw:3,r:10})+SG_T(X+55,Y+38,t,{fs:24,fw:800,a:'middle'});
  return `<g transform="translate(${x-210} ${y-165})">${SG_T(0,40,'x',{fs:30,fw:800,fill:BLU})}${SG_arrow(26,30,70,30)}${bx(76,2,'delay')}${SG_arrow(192,30,236,30)}${bx(242,2,'T')}${SG_arrow(358,30,402,30)}${SG_T(0,156,'x',{fs:30,fw:800,fill:BLU})}${SG_arrow(26,146,70,146)}${bx(76,118,'T')}${SG_arrow(192,146,236,146)}${bx(242,118,'delay')}${SG_arrow(358,146,402,146)}${SG_box(70,214,280,64,{fill:'#FFF3BF',st:YEL,sw:3,r:12})}${SG_T(210,256,'same? then TI',{fs:28,fw:800,a:'middle'})}${SG_T(210,318,'one mismatch fails a test',{fs:22,a:'middle',fill:'#5C6577'})}</g>`};
 ICON.sgHS=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${SG_L(0,140,420,140,'#ADB5BD',2)}${SG_area(SG_h,0,1,20,100,140,110,ORG,.25)}${SG_curve(SG_h,0,5,20,420,140,110,ORG,5)}${SG_T(150,60,'h(t)',{fs:28,fw:800,fill:ORG})}${SG_L(0,320,420,320,'#ADB5BD',2)}${SG_curve(SG_s,0,5,20,420,320,130,BLU,5)}${SG_T(150,236,'s(t) = ∫ h',{fs:28,fw:800,fill:BLU})}</g>`;
 ICON.sgRCnum=(x,y)=>{const X=t=>20+t*78,Yh=v=>150-v*120,Ys=v=>320-v*130;
  return `<g transform="translate(${x-210} ${y-165})">${SG_L(10,150,420,150,'#ADB5BD',2)}${SG_curve(SG_h,0,5,20,410,150,120,ORG,5)}${SG_L(X(1),150,X(1),Yh(Math.exp(-1)),ORG,2,'stroke-dasharray="5 5"')}<circle cx="${X(1)}" cy="${Yh(Math.exp(-1)).toFixed(1)}" r="8" fill="${ORG}"/>${SG_T(X(1)+16,Yh(Math.exp(-1))-8,'368 s⁻¹',{fs:26,fw:800,fill:ORG})}${SG_L(10,320,420,320,'#ADB5BD',2)}${SG_curve(SG_s,0,5,20,410,320,130,BLU,5)}${SG_L(X(1),320,X(1),Ys(SG_s(1)),BLU,2,'stroke-dasharray="5 5"')}<circle cx="${X(1)}" cy="${Ys(SG_s(1)).toFixed(1)}" r="8" fill="${BLU}"/>${SG_T(X(1)+16,Ys(SG_s(1))+30,'0.632',{fs:26,fw:800,fill:BLU})}${SG_T(X(1),346,'τ',{fs:24,fw:800,a:'middle',fill:'#5C6577'})}</g>`};
}
